    "使用须知": "Hinweis zur Nutzung",
    "FMODD 中的投注、赔率、赌场等相关功能，仅用于丰富 Football Manager 的游戏体验，与现实世界中的赌博、博彩及现金交易无任何关联。严禁将本工具用于任何形式的现实赌博、非法投注或其他违法违规活动。": "FMODD's betting, Quoten und casino features vorhanden nur zu enhance der Football Manager experience. They haben kein Verbindung mit real-Welt gambling, betting oder cash transactions. Never Verwenden dieser tool für real-Welt gambling, illegal betting oder other unlawful Aktivität.",
    "本工具永久免费。如您喜欢本工具，可以在“设置”中留言并投喂作者。": "FMODD ist kostenlos. Wenn es dir gefällt, kannst du den Autor in den Einstellungen unterstützen.",
    "您的支持是 FMODD 持续更新和完善的最大动力。": "Deine Unterstützung hilft, FMODD weiterzuentwickeln.",
    "请尽量避免在比赛加载、保存游戏或度假过程中使用相关功能，以减少未知错误。": "Verwende die betreffenden Funktionen möglichst nicht während des Ladens eines Spiels, beim Speichern oder im Urlaub, um unbekannte Fehler zu vermeiden.",
    "严禁任何个人或组织以 FMODD 名义进行收费售卖、付费授权、捆绑销售或其他牟利行为。请勿购买任何所谓的“付费版”或“授权版”，谨防受骗。": "FMODD müssen nicht sein sold, licensed für ein Gebühr, bundled für Gewinn oder otherwise monetised durch any Person oder organisation. Do nicht Kaufen any alleged bezahlt oder licensed edition; beware von scams.",
    "因 Football Manager 游戏版本存在差异，部分功能可能失效或导致数据异常。": "Football Manager Version differences may cause some features zu fail oder produce unexpected Daten.",
    "FMODD 仍在持续更新和完善中。如您遇到错误、需要反馈问题、获取最新版本或参与交流，请加入官方 QQ 群：": "FMODD wird aktiv weiterentwickelt. Für Fehler, Feedback, Updates und Diskussionen tritt bitte der offiziellen QQ-Gruppe bei:",
