    "将建立一年租借，并保留母队合同与名单。": "Es wird eine einjährige Leihe erstellt; Vertrag und Kaderzuordnung beim Mutterverein bleiben erhalten.",
    "租借成功": "Darlehen abgeschlossen",
    "请在青训预览日之前使用；每年 1 月 1 日恢复 1 个名额。主位置固定 20，副位置可不选；选择时固定 12，其余位置为 1，姓氏及第一国籍继承玩家。名字留空时沿用候选原名。正式名单人数不足时自动提示并退款。": "Vor dem Jugendvorschautermin verwenden. Am 1. Januar wird jeweils ein Platz zurückgegeben. Die Hauptposition ist fest auf 20 gesetzt; die Nebenposition ist optional und bei Auswahl fest auf 12 gesetzt, alle anderen Positionen sind 1. Nachname und erste Nationalität werden vom Spieler übernommen. Bei leerem Namen bleibt der ursprüngliche Name des Kandidaten erhalten. Bei einer zu kleinen endgültigen Aufnahme wird automatisch erstattet.",
    "请在青训预览日之前使用；与儿子历练互不冲突。正式名单人数不足时按缺少名额自动退款。": "Verwenden vor der youth Vorschau Datum. It does nicht conflict mit Sohn Entwicklung. fehlend places in der endgültig Aufnahme sind erstattet automatisch.",
