    "理论最高可借额度为主教练税前周薪的 {multiplier} 倍，即 {limit}。": "der theoretical Maximum Darlehen ist {multiplier} times der head Trainer's gross weekly Gehalt: {limit}.",
    "根据您当前信用评级，本次最高可借额度为主教练税前周薪的 {multiplier} 倍，即 {limit}。": "auf Grundlage on dein aktuell Kredit rating, der Maximum Darlehen für dieser request ist {multiplier} times der head Trainer's gross weekly Gehalt: {limit}.",
    "借款将在确认后立即存入账户，并自到账之日起开始计息；当日归还也会收取一天利息。借款期限为 30 个游戏日，利息按未偿还本金的每日 0.5% 单利计算。": "Das Darlehen wird unmittelbar nach der Bestätigung auf das Konto eingezahlt und ab dem Tag seines Eingangs verzinst; auch bei Rückzahlung am selben Tag fällt ein Tageszins an. Die Laufzeit beträgt 30 Spieltage, mit einfachen Zinsen von 0,5 % pro Tag auf den unbezahlten Hauptbetrag.",
    "借款期间可随时提前偿还部分或全部本金，不收取提前还款费用。所有还款将优先用于偿还利息，剩余金额再冲抵本金。": "während der Laufzeit, du may repay part oder alle von der principal vorzeitig at any Zeit ohne ein vorzeitig-Rückzahlung Gebühr. Repayments erste cover interest; any remainder reduces der principal.",
    "到期后，系统将依次从以下账户自动扣款：": "At maturity, der System automatisch deducts Mittel in dieser order:",
    "银行账户余额": "Bank account Guthaben",
    "赌场钱包余额": "Casino Wallet Guthaben",
    "如全部资金仍不足以清偿债务，系统将启动违约处置程序，根据剩余待还金额占原始贷款本金的比例，对与主教练亲密度最高的 1–10 名球员施加随机属性或伤病惩罚。": "If alle Mittel sind still unzureichend zu Leeren der Schulden, der System wird starten Standard handling und apply ein Zufällig Attribut oder Verletzung Elfmeter zu 1–10 Spieler mit der highest Vertrautheit mit der head Trainer, according zu der ratio von verbleibend Schulden zu der original Darlehen principal.",
    "请确认你已了解借款额度、计息方式、到期时间及违约后果。": "bitte Bestätigen dieser du understand der Darlehen Betrag, interest calculation, due Datum und consequences von Standard.",
